-- HG Industries' customer and warehouse cities as locations, for the book's
-- appendix on spatial data. GENERATED by scripts/build-hg-locations.py; do not
-- edit.
--
-- Run it in dbconcepts_history, which holds the year of history
-- (load/through-s.sql).
-- It needs PostGIS installed with the server (Postgres.app includes it), and a
-- user allowed to create an extension: the user the PostgreSQL installation
-- made for you is. Running it again replaces the table.
--
-- The table is in a schema of its own, geo, joined to distribution.customer and
-- distribution.warehouse on (city, state). It has no foreign key to them, so a
-- reload of the book's schemas (through-s.sql) leaves it in place.
--
-- Coordinates: U.S. Census Bureau, 2025 Gazetteer Files, places
-- (public domain):
-- https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2025_Gazetteer/2025_Gaz_place_national.zip
-- Each is the place's internal point (INTPTLAT, INTPTLONG): one point inside
-- the city's boundary, not its center and not any address in it. geoid is
-- the Census Bureau's identifier for the place.

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE SCHEMA IF NOT EXISTS geo;

DROP TABLE IF EXISTS geo.city_location;

CREATE TABLE geo.city_location (
    city_location_pk INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    city             VARCHAR(40)    NOT NULL,
    state            CHAR(2)        NOT NULL,
    geoid            CHAR(7)        NOT NULL UNIQUE,
    latitude         NUMERIC(8, 6)  NOT NULL
        CHECK (latitude BETWEEN -90 AND 90),
    longitude        NUMERIC(9, 6)  NOT NULL
        CHECK (longitude BETWEEN -180 AND 180),
    location         geography(Point, 4326)
        GENERATED ALWAYS AS (
            ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)::geography
        ) STORED,
    UNIQUE (city, state)
);

